import itertools
import xml.etree.ElementTree as ET
from ast import literal_eval as make_tuple
from string import Template


def findcontain(elem, tag):
    for child in elem:
        if tag in child.tag:
            return child
    return None


def findallcontain(elem, tag):
    temp = []
    for child in elem:
        if tag in child.tag:
            temp.append(child.text.replace(' ', '_'))
    return temp


def str2bool(v):
    return v.lower() in ("yes", "true", "t", "1")


def xml_to_python(path):
    tree = ET.parse(path)

    root = tree.getroot()
    CSP = root.find('CSP')

    domains = {}
    positions = {}
    constraints = []
    name = CSP.find('NAME').text.replace(' ', '_')

    for i in CSP:
        if i.tag == 'VARIABLE':
            mytype = i.get('TYPE')
            if(mytype == 'Integer'):
                pass
            elif(mytype == 'String'):
                pass
            elif(mytype == 'Boolean'):
                pass
            varDomain = []
            for e in i:
                if e.tag == 'NAME':
                    varName = e.text
                if e.tag == 'VALUE':
                    if(mytype == 'Integer'):
                        varDomain.append(int(e.text))
                    elif(mytype == 'String'):
                        varDomain.append(e.text)
                    elif(mytype == 'Boolean'):
                        varDomain.append(str2bool(e.text))
                if e.tag == 'PROPERTY':
                    positions[varName] = make_tuple(e.text.split('=')[1][1:])

            domains[varName] = varDomain
        elif i.tag == 'CONSTRAINT':
            if i.get('TYPE') == 'Custom':
                relatedvar = []
                table = []
                for e in i:
                    if e.tag == 'GIVEN':
                        relatedvar.append(e.text)
                    elif e.tag == 'TABLE':
                        table = e.text.split(" ")
                table = ['T' in x for x in table]
                trueTuples = []
                targetlist = [domains[x] for x in relatedvar]
                allTuple = list(itertools.product(*targetlist))
                for i in range(0, len(allTuple)):
                    if table[i]:
                        trueTuples.append(str(allTuple[i]))
                relatedvarName = ["'" + x + "'" for x in relatedvar]
                constraints.append(Template('Constraint(($var),lambda $vNames: ($vNames) in [$true])').substitute(
                    var=','.join(relatedvarName),
                    vNames=','.join(relatedvar),
                    true=','.join(trueTuples)
                ))
            else:
                relatedvar = []
                complement = False
                for e in i:
                    if e.tag == 'GIVEN':
                        relatedvar.append(e.text)
                    elif e.tag == 'ARGS':
                        if e.text != None and 'complement' in e.text:
                            complement = True
                relatedvarName = ["'" + x + "'" for x in relatedvar]
                if complement:
                    constraints.append(Template('Constraint(($var),NOT($function))').substitute(
                        var=','.join(relatedvarName),
                        function=i.get('TYPE')
                    ))
                else:
                    constraints.append(Template('Constraint(($var),$function)').substitute(
                        var=','.join(relatedvarName),
                        function=i.get('TYPE')
                    ))

    template = """$name = CSP(
        domains=$domains,
        constraints=[$constraints],
        positions=$positions)"""

    print(Template(template).substitute(
        name=name,
        domains=domains,
        constraints=', '.join(constraints),
        positions=positions))

"""
Support to communicate with a Buderus KM200 unit.
"""

import logging
import base64
import json
import binascii
import urllib.request, urllib.error, urllib.parse
import voluptuous as vol
from io import StringIO
from Crypto.Cipher import AES

from homeassistant.helpers import config_validation as cv
from homeassistant.const import (CONF_HOST, CONF_PASSWORD, CONF_NAME)

DOMAIN = 'buderus'

DEFAULT_NAME = 'Buderus'

CONFIG_SCHEMA = vol.Schema({
    DOMAIN: vol.Schema({
        vol.Required(CONF_HOST): cv.string,
        vol.Required(CONF_PASSWORD): cv.string,
        vol.Optional(CONF_NAME, default=DEFAULT_NAME): cv.string,
    }),
}, extra=vol.ALLOW_EXTRA)

def setup(hass, config):
    conf = config[DOMAIN]
    
    host = conf.get(CONF_HOST)
    name = conf.get(CONF_NAME)
    password = conf.get(CONF_PASSWORD)
	
    bridge = BuderusBridge(name, host, password)
	
    hass.data[DOMAIN] = bridge

    return True

class BuderusBridge(object):
    BS = AES.block_size
    INTERRUPT = '\u0001'
    PAD = '\u0000'

    def __init__(self, name, host, password):
        self.logger = logging.getLogger(__name__)
        self.logger.info("Init Buderus")
        self.__ua = "TeleHeater/2.2.3"
        self.__content_type = "application/json"
        self._host = host
        self._key = binascii.unhexlify(password)
        self._ids = {}
        self.opener = urllib.request.build_opener()
        self.opener.addheaders = [('User-agent', self.__ua), ('Accept', self.__content_type)]
        self.name = name

    def _decrypt(self, enc):
        decobj = AES.new(self._key, AES.MODE_ECB)
        data = decobj.decrypt(base64.b64decode(enc))
        data = data.rstrip(self.PAD.encode()).rstrip(self.INTERRUPT.encode())
        return data

    def _encrypt(self, plain):
        plain = plain + (AES.block_size - len(plain) % self.BS) * self.PAD
        encobj = AES.new(self._key, AES.MODE_ECB)
        data = encobj.encrypt(plain.encode())
        return base64.b64encode(data)

    def _get_data(self, path):
        try:
            url = 'http://' + self._host + path
            self.logger.debug("Buderus fetching data from {}".format(path))
            resp = self.opener.open(url)
            plain = self._decrypt(resp.read())
            self.logger.debug("Buderus data received from {}: {}".format(url, plain))
            return plain
        except Exception as e:
            self.logger.error("Buderus error happened at {}: {}".format(url, e))
            return None
            
    def _get_json(self, data):
        try:
            j = json.load(StringIO(data.decode()))
            return j
        except Exception as e:
            self.logger.error("Buderus error happened while reading JSON data {}: {}".format(data, e))
            return False
            
    def _get_value(self, j):
        return j['value']
        
    def _json_encode(self, value):
        d = {"value": value}
        return json.dumps(d)
        
    def _set_data(self, path, data):
        try:
            url = 'http://' + self._host + path
            self.logger.info("Buderus setting value for {}".format(path))
            headers = {"User-Agent": self.__ua, "Content-Type": self.__content_type}
            request = urllib.request.Request(url, data=data, headers=headers, method='PUT')
            req = urllib.request.urlopen(request)
            self.logger.info("Buderus returned {}: {}".format(req.status, req.reason))
            if not req.status == 204:
                self.logger.debug(req.read())
        except Exception as e:
            self.logger.error("Buderus error happened at {}: {}".format(url, e))
            return None
            
    def _submit_data(self, path, data):
        self.logger.info("Buderus SETTING {} to {}".format(path, data))
        payload = self._json_encode(data)
        self.logger.debug(payload)
        req = self._set_data(path, self._encrypt(str(payload)))

