		class ChannelSelectionEditActionMap(ActionMap):
			def __init__(self, csel, contexts=None, actions=None, prio=0):
				if not contexts: contexts = []
				if not actions: actions = {}
				ActionMap.__init__(self, contexts, actions, prio)
