def get_map_key_type(tp):
    assert tp[0] == '<', tp
    assert tp[-1] == '>'
    ret = ""
    balance = 0
    for ch in tp[1:-1]:
        if ch == '<':
            balance += 1
        elif ch == '>':
            assert balance > 0
            balance -= 1
        elif ch == '|' and balance == 0:
            break
        ret += ch
    return ret


def get_map_value_type(tp):
    assert tp[0] == '<', tp
    assert tp[-1] == '>'
    ret = ""
    balance = 0
    saw_pipe = False
    for ch in tp[1:-1]:
        if saw_pipe:
            ret += ch
        if ch == '<':
            balance += 1
        elif ch == '>':
            assert balance > 0
            balance -= 1
        elif ch == '>':
            assert saw_pipe
            break
        elif ch == '|' and balance == 0:
            saw_pipe = True
    return ret


