    funcs['>='] = lambda x, y: x >= y
    funcs['*'] = lambda x, y: x * y
    funcs['/'] = lambda x, y: x // y if not isinstance(x, float) and not isinstance(y, float) else x / y
    funcs['%'] = lambda x, y: x % y
    funcs['+'] = lambda x, y: x + y
    funcs['-'] = lambda x, y: x - y
